      "description": "Specifies the type of entity to be created. This is a mandatory field and must contain one of the predefined values listed. Supported entities include: location, costCenter, subLocation, salaryGrade, corporateTitle, designation, jobDescriptionCategory, jobDescriptionType, qualificationType, ratingMethod, membershipType, membershipDetails, membershipTitle, bargainingUnit, cashBenefit, nonCashBenefitCategory, nonCashBenefit, employeeCategory, statutoryClassification, function, functionalRoles, classification, employeeGroup, employmentType, employeeTitle, genderType, maritalStatus, bloodGroup, and attachmentType. This field is essential for identifying the module under which the creation request will be processed."
    },
    "location": {
      "title": "LocationFormData",
      "type": "object",
      "description": "To create a location: Always collect required fields. For optional fields, only ask if the user provides related input. First, fetch values using the getDistrictDetails tool. If the user provides names like country, province, or district directly, map them to their corresponding codes using getSelectLocationDetails. If no input is given, fall back to tool-provided values.",
      "properties": {
        "ctl00_body_txtName": {
          "type": "string",
          "description": "Full name of the location. Prefer user input when available."
        },
        "ctl00_body_txtAbbreviation": {
          "type": "string",
          "description": "Abbreviation for the location. Use user input when provided."
        },
        "ctl00_body_txttp": {
          "type": "string",
          "description": "Telephone number for the location. Use user input."
        },
        "ctl00_body_txtFax": {
          "type": "string",
          "description": "Fax number for the location. Use user input."
        },
        "ctl00_body_txtemail": {
          "type": "string",
          "format": "email",
          "description": "Email address of the location. Use user input."
        },
        "ctl00_body_txturl": {
          "type": "string",
          "format": "uri",
          "description": "Website URL of the location. Use user input."
        },
        "ctl00_body_txtaddress": {
          "type": "string",
          "description": "Physical address of the location. Use user input."
        },
        "ctl00_body_ddlCountry": {
          "type": "string",
          "description": "Country code (e.g., '000012'). If the user provides a country name, map it to its code using getSelectLocationDetails. Otherwise, use the fallback value from the tool."
        },
        "ctl00_body_ddlProvince": {
          "type": "string",
          "description": "Province code (e.g., '000012'). If the user provides a province name, map it to its code using getSelectLocationDetails. Otherwise, use the fallback value from the tool."
        },
        "ctl00_body_ddlDistrict": {
          "type": "string",
          "description": "District code (e.g., '000012'). If the user provides a district name, map it to its code using getSelectLocationDetails. Otherwise, use the fallback value from the tool."
        },
        "ctl00_body_cboTimeZone": {
          "type": "string",
          "description": "Time zone of the location. Use user input."
        },
        "ctl00_body_txtHeadName": {
          "type": "string",
          "description": "Name of the head of the location. Use user input."
        },
        "ctl00_body_txtHTitle": {
          "type": "string",
          "description": "Title/designation of the head of the location. Use user input."
        },
        "ctl00_body_txtAdminName": {
          "type": "string",
          "description": "Name of the administrator for the location. Use user input."
        },
        "ctl00_body_filMyFile": {
          "type": "string",
          "contentEncoding": "base64",
          "title": "Logo File",
          "description": "Logo file in base64 encoding. Optional input, use only if provided."
        },
        "ctl00_body_butSave": {
          "type": "string",
          "enum": [
            "Save"
          ],
          "description": "Save action trigger. Always set this to 'Save'."
        },
        "ctl00_body_hdnDefCountry": {
          "type": "string",
          "description": "Default country code. Use user input when available."
        }
      },
      "required": [
        "ctl00_body_txtName",
        "ctl00_body_ddlCountry",
        "ctl00_body_ddlProvince",
        "ctl00_body_ddlDistrict"
      ]
    },
    "costCenter": {
      "type": "object",
      "properties": {
        "costCentreName": {
