        "costCentreName"
      ]
    },
    "subLocation": {
      "type": "object",
      "description": "To create a new sub-location, first fetch all available locations using the getSelectLocations API and display the location names for the user to select. Once a location is selected, automatically retrieve the corresponding location ID. The 'Head of Sub Location' field is optional however, if the user provides an employee ID, the corresponding employee name should be automatically fetched and populated. The 'Head of Sub Location' name remains optional during the creation process.",
      "properties": {
        "ctl00_body_txtName": {
          "type": "string",
          "description": "Name or description of the sub-location, e.g., 'Colomboo'."
        },
        "ctl00_body_ddlLocation": {
          "type": "string",
          "description": "Selected location ID from the dropdown, e.g., '000002'. This value should be retrieved from the available locations using the getSubLocationDetails API. The user must select the corresponding value or id."
        },
        "ctl00_body_txtHeadName": {
          "type": "string",
          "description": "Head of Sub Location name, e.g., 'Peter Pascal'. This is an optional field. If provided, the corresponding employee ID should be fetched using the getEmployeeDetails API."
        }
      },
      "required": [
        "ctl00_body_txtName",
        "ctl00_body_ddlLocation"
      ]
    },
    "salaryGrade": {
      "type": "object",
      "description": "Before Execute in this tool. first execute the getCurrencyDetails Api then display available currency name then pic the currency name corresponding value will be take.",
      "properties": {
        "ctl00_body_txtsalname": {
          "type": "string",
          "description": "Salary Grade Name (e.g., GCB Grade 04)."
        },
        "ctl00_body_cboCurrType": {
          "type": "string",
          "description": "Selected currency code (e.g., 000001 for AED). display the currency list to selected the currency name to get corresponding value for getCurrencyDetails api"
        },
        "ctl00_body_txtMin": {
          "type": "number",
          "description": "Minimum salary point. It must be less than equal to the Mid Point."
        },
        "ctl00_body_txtMid": {
          "type": "number",
          "description": "Mid salary point. It must be greater than the Min Point and less than equal to the Max Point."
        },
        "ctl00_body_txtMax": {
          "type": "number",
          "description": "Maximum salary point. It must be greater than equal to the Mid Point."
        }
      },
      "required": [
        "ctl00_body_txtsalname",
        "ctl00_body_cboCurrType",
        "ctl00_body_txtMin",
        "ctl00_body_txtMid",
        "ctl00_body_txtMax"
      ]
    },
    "corporateTitle": {
      "type": "object",
      "description": "Before creating a Corporate Title,must and should execute for 'getUpgradeLevelandSalaryGrade' tool then display the all salary grades,The Salary Grade options must be shown to the user, who will then select a name, and the corresponding value must be captured. If the user marks 'Top in Hierarchy' as enabled (on), the Next Upgrade Level field should not be displayed. However, if 'Top in Hierarchy' is disabled (off), the Next Upgrade Level options must be shown, and the user should select the appropriate value from the list. top Hierarchy is optional field if the user add then condations implement other then not required dont display the next upgrade details.",
      "properties": {
        "ctl00_body_txtName": {
          "type": "string",
          "description": "Corporate Title Name (e.g., 'Middle Management').in this field is required must and should provide the user"
        },
        "ctl00_body_dpSalary": {
          "type": "string",
          "description": "Selected Salary Grade code (e.g., '000005'). All Salary Grades data for getUpdateCorporateTitleDetails api will be displayed for the user to select, and the corresponding value must be picked.and in this field is required must and should provide the user"
        },
        "ctl00_body_chkTop": {
          "type": "string",
          "enum": [
            "on"
          ],
          "description": "Top in Hierarchy flag. If provided as 'on', 'Next Upgrade Level' must NOT be passed. in this field is optional field"
        },
        "ctl00_body_dpNextUpgrade": {
          "type": "string",
          "description": "Next Upgrade Level code (e.g., '000008'). this field is optional This must be provided if 'Top in Hierarchy' is not 'on'. and user off to display the all next upgrade level detaisl for retrive the data for getUpdateCorporateTitleDetails api"
        },
        "ctl00_body_nuLevel": {
          "type": "integer",
          "description": "Level number (e.g., 3)."
        },
        "ctl00_body_ManagePos": {
          "type": "string",
          "enum": [
            "on",
            "off"
          ],
          "description": "Indicates whether it is a Managerial Position. on or off"
        }
      },
      "required": [
        "ctl00_body_txtName",
        "ctl00_body_dpSalary"
      ],
      "dependencies": {
        "ctl00_body_chkTop": {
          "oneOf": [
            {
              "properties": {
                "ctl00_body_chkTop": {
                  "const": "on"
                }
              },
              "not": {
                "required": [
                  "ctl00_body_dpNextUpgrade"
                ]
              }
            },
            {
              "not": {
                "required": [
                  "ctl00_body_chkTop"
                ]
              },
              "required": [
                "ctl00_body_dpNextUpgrade"
              ]
            }
          ]
        }
      }
    },
    "designation": {
      "type": "object",
      "description": "This tool is used to create a Designation. First, it executes the gradeDetails API to retrieve and select the appropriate salary grade value. After selecting the salary grade, it then executes the getTitle API to retrieve and select the corresponding corporate title value. The steps must be followed in sequence: first execute gradeDetails, then execute getTitle.",
      "properties": {
        "ctl00_body_txtName": {
          "type": "string",
          "description": "Designation name (e.g., 'Human Resources Manager')."
        },
        "ctl00_body_chksenior": {
          "type": "string",
          "enum": [
            "on",
            "off"
          ],
          "description": "selsect senior management 'on' or 'off'."
        },
        "ctl00_body_dpSalary": {
          "type": "string",
          "description": "Selected Salary Grade code (e.g., '000005')."
        },
        "ctl00_body_dpNextUpgrade": {
          "type": "string",
          "description": "Selected Corporate Title or Next Upgrade Level code (e.g., '000001')."
