        },
        "ctl00_body_cbofunctionRole": {
          "type": "string",
          "description": "Selected Functional Role code (e.g., '000001').if the user missing fields to get data for getTitle api"
        }
      },
      "required": [
        "ctl00_body_txtName",
        "ctl00_body_chksenior",
        "ctl00_body_dpSalary",
        "ctl00_body_dpNextUpgrade"
      ]
    },
